}

Method.Source:
/// <summary>
/// PaffH 06.02.24
/// </summary>
/// <param name = "_args">Args</param>
/// <returns>AVABPJobProtController</returns>
public static AVABPJobProtController newFromArgs(Args _args)
{
    AVABPJobProtController controller = next newFromArgs(_args);
    if (_args.caller() is NDXKBVBuildingProject2RicoKalk)
    {
        controller.parmLoadFromSysLastValue(false);
        controller.parmShowDialog(false);
        AVABPJobsContract contract = controller.getDataContractObject();
        if (contract)
        {
            contract.parmUpdateResponsibilities(NoYes::No);
            contract.parmUpdateSalesVolume(NoYes::Yes);
            contract.parmUpdateSalesVolumeGLB(NoYes::Yes);
        }
    }
    return controller;
}
